-- ============================================================
-- PM System - Task SOP Integration Migration
-- ============================================================

-- 1. New table: quotation_item_templates
CREATE TABLE IF NOT EXISTS quotation_item_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  item_name TEXT NOT NULL,
  task_category TEXT NOT NULL,
  task_name TEXT NOT NULL,
  reference_point TEXT NOT NULL,
  offset_days INTEGER NOT NULL DEFAULT 0,
  duration_days INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Alter tasks table
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS source_item TEXT;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS task_category TEXT;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS reference_point TEXT;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS start_date DATE;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS duration_days INTEGER;

-- 3. Alter projects table: add reference date columns and tags
ALTER TABLE projects ADD COLUMN IF NOT EXISTS event_online_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS event_end_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS material_confirm_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS physical_event_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS system_online_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS monthly_settle_date DATE;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS tags TEXT[] DEFAULT '{}';

-- Make project_type nullable (keep column but no longer required)
ALTER TABLE projects ALTER COLUMN project_type DROP NOT NULL;
ALTER TABLE proposals ALTER COLUMN project_type DROP NOT NULL;

-- 4. RLS for quotation_item_templates
ALTER TABLE quotation_item_templates ENABLE ROW LEVEL SECURITY;

CREATE POLICY qit_select ON quotation_item_templates
  FOR SELECT TO authenticated USING (true);

CREATE POLICY qit_insert ON quotation_item_templates
  FOR INSERT TO authenticated
  WITH CHECK (get_user_role() IN ('admin', 'operations'));

CREATE POLICY qit_update ON quotation_item_templates
  FOR UPDATE TO authenticated
  USING (get_user_role() IN ('admin', 'operations'))
  WITH CHECK (get_user_role() IN ('admin', 'operations'));

CREATE POLICY qit_delete ON quotation_item_templates
  FOR DELETE TO authenticated
  USING (get_user_role() = 'admin');

-- 5. Indexes
CREATE INDEX idx_qit_item_name ON quotation_item_templates(item_name);
CREATE INDEX idx_qit_task_category ON quotation_item_templates(task_category);
CREATE INDEX idx_tasks_source_item ON tasks(source_item);
CREATE INDEX idx_tasks_task_category ON tasks(task_category);
CREATE INDEX idx_projects_tags ON projects USING GIN(tags);

-- 6. Trigger for updated_at
CREATE TRIGGER trg_qit_updated_at
  BEFORE UPDATE ON quotation_item_templates
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

